import { test } from "node:test";
import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g2-1/bot.mjs";

let n = 0;
const uid = () => `u${++n}`;
const mk = (over = {}) => ({
  userId: uid(), category: "marketing", timezone: "Europe/Istanbul",
  quietStart: "22:00", quietEnd: "07:30", ...over,
});

test("transactional always sent, rule null, even in quiet hours and past cap", () => {
  const u = uid();
  const c = mk({ userId: u, category: "transactional" });
  const at = new Date("2026-10-23T20:30:00Z"); // Istanbul 23:30, quiet
  for (let i = 0; i < 10; i++) assert.deepEqual(decide(c, at), { send: true, rule: null });
});

test("marketing capped at 3 per local day, 4th gets daily-cap", () => {
  const c = mk();
  const at = new Date("2026-10-23T08:00:00Z"); // Istanbul 11:00
  for (let i = 0; i < 3; i++) assert.deepEqual(decide(c, at), { send: true, rule: null });
  assert.deepEqual(decide(c, at), { send: false, rule: "daily-cap" });
});

test("transactional sends do not count toward marketing cap", () => {
  const u = uid();
  const at = new Date("2026-10-23T08:00:00Z");
  for (let i = 0; i < 5; i++) decide(mk({ userId: u, category: "transactional" }), at);
  const c = mk({ userId: u });
  for (let i = 0; i < 3; i++) assert.equal(decide(c, at).send, true);
  assert.equal(decide(c, at).rule, "daily-cap");
});

test("cap resets on the customer's local day, not UTC", () => {
  const c = mk({ timezone: "Asia/Tokyo" });
  // 2026-10-23T14:30Z = Tokyo 23:30 on Oct 23
  const before = new Date("2026-10-23T14:30:00Z");
  // 2026-10-23T15:30Z = Tokyo 00:30 on Oct 24 (UTC still Oct 23)
  const after = new Date("2026-10-23T15:30:00Z");
  for (let i = 0; i < 3; i++) decide(c, before);
  assert.equal(decide(c, before).rule, "daily-cap");
  assert.deepEqual(decide(c, after), { send: true, rule: null });
});

test("cap is per local day for a west-of-UTC customer", () => {
  const c = mk({ timezone: "America/New_York", quietStart: "00:00", quietEnd: "00:00" });
  // 2026-10-23T03:00Z = New York Oct 22 23:00 (UTC already Oct 23)
  const lateNight = new Date("2026-10-23T03:00:00Z");
  // 2026-10-23T14:00Z = New York Oct 23 10:00
  const morning = new Date("2026-10-23T14:00:00Z");
  for (let i = 0; i < 3; i++) decide(c, lateNight);
  assert.equal(decide(c, lateNight).rule, "daily-cap");
  assert.deepEqual(decide(c, morning), { send: true, rule: null });
});

test("quiet window crossing midnight: inside blocked, edges right", () => {
  const c = mk();
  // Istanbul is UTC+3, no DST.
  assert.equal(decide(c, new Date("2026-10-23T20:30:00Z")).rule, "quiet-hours"); // 23:30
  assert.equal(decide(c, new Date("2026-10-23T21:00:00Z")).rule, "quiet-hours"); // 00:00
  assert.equal(decide(c, new Date("2026-10-23T04:29:00Z")).rule, "quiet-hours"); // 07:29
  assert.equal(decide(c, new Date("2026-10-23T19:00:00Z")).rule, "quiet-hours"); // 22:00 start inclusive
  assert.deepEqual(decide(c, new Date("2026-10-23T04:30:00Z")), { send: true, rule: null }); // 07:30 end exclusive
  assert.deepEqual(decide(c, new Date("2026-10-23T08:00:00Z")), { send: true, rule: null }); // 11:00
});

test("quiet window within one day", () => {
  const c = mk({ quietStart: "13:00", quietEnd: "14:00" });
  assert.equal(decide(c, new Date("2026-10-23T10:30:00Z")).rule, "quiet-hours"); // 13:30
  assert.deepEqual(decide(c, new Date("2026-10-23T11:00:00Z")), { send: true, rule: null }); // 14:00
});

test("quiet-hours blocked marketing does not count toward cap", () => {
  const u = uid();
  const c = mk({ userId: u });
  for (let i = 0; i < 5; i++) assert.equal(decide(c, new Date("2026-10-23T20:30:00Z")).rule, "quiet-hours");
  assert.equal(decide(c, new Date("2026-10-23T08:00:00Z")).send, true);
});

test("quiet-hours checked before cap: rule names the one that stopped it", () => {
  const u = uid();
  const c = mk({ userId: u });
  for (let i = 0; i < 3; i++) decide(c, new Date("2026-10-23T08:00:00Z"));
  // Capped and in quiet hours: quiet-hours wins by order.
  assert.equal(decide(c, new Date("2026-10-23T20:30:00Z")).rule, "quiet-hours");
});

test("start equal to end means no quiet window", () => {
  const c = mk({ quietStart: "09:00", quietEnd: "09:00" });
  assert.deepEqual(decide(c, new Date("2026-10-23T06:00:00Z")), { send: true, rule: null }); // 09:00
});

test("DST: New York fall-back day uses local clock", () => {
  const c = mk({ timezone: "America/New_York", quietStart: "01:30", quietEnd: "02:30" });
  // 2026-11-01 05:45Z = 01:45 EST (after fall back at 06:00Z)? 01:45 EDT is 05:45Z.
  assert.equal(decide(c, new Date("2026-11-01T05:45:00Z")).rule, "quiet-hours");
});

test("invalid input throws", () => {
  const ok = mk();
  const now = new Date("2026-10-23T08:00:00Z");
  assert.throws(() => decide({ ...ok, category: "promo" }, now), TypeError);
  assert.throws(() => decide({ ...ok, quietStart: "24:00" }, now), TypeError);
  assert.throws(() => decide({ ...ok, quietEnd: "7:30" }, now), TypeError);
  assert.throws(() => decide({ ...ok, timezone: "Mars/Olympus" }, now), RangeError);
  assert.throws(() => decide(ok, "2026-10-23"), TypeError);
  assert.throws(() => decide(ok, new Date("nope")), TypeError);
});

test("bad input on transactional still throws only where validated (transactional skips window check)", () => {
  // Transactional returns before reading quiet/timezone, so it does not validate them.
  assert.deepEqual(decide({ userId: uid(), category: "transactional", timezone: "bogus", quietStart: "x", quietEnd: "y" }, new Date()), { send: true, rule: null });
});
EOF
